url":null},{"name":"Primient","slug":"primient","domain":"primient.com","description":"Provider of nutritive sweeteners, industrial starches, acidulants and other corn-derived products.","sector":null,"hq":"USA","status":"current","invested_year":2022,"exit_year":null,"fund_name":"Fund V","source_url":"https://kpsfund.com/investments/primient/","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Speira","slug":"speira","domain":"speira.com","description":"Manufacturer of advanced rolled aluminum products.","sector":null,"hq":"Germany","status":"current","invested_year":2021,"exit_year":null,"fund_name":"Fund V","source_url":"https://kpsfund.com/investments/speira/","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"AM General","slug":"am-general","domain":"amgeneral.com","description":"Designer, engineer and manufacturer of light tactical vehicles, including the HUMVEE.","sector":null,"hq":"South Bend, Indiana, USA","status":"current","invested_year":2020,"exit_year":null,"fund_name":"Fund V","source_url":"https://kpsfund.com/investments/am-general/","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Briggs & Stratton","slug":"briggs-and-stratton","domain":"briggsandstratton.com","description":"Producer of gasoline engines for outdoor power equipment and of turf care products, batteries, standby generators and energy storage systems.","sector":null,"hq":"Milwaukee, Wisconsin, USA","status":"current","invested_year":2020,"exit_year":null,"fund_name":"Fund V","source_url":"https://kpsfund.com/investments/briggs-stratton/","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Lufkin Industries","slug":"lufkin-industries","domain":"lufkin.com","description":"Provider of rod lift products, technologies, services and solutions to the oil and gas industry.","sector":null,"hq":"Missouri City, Texas, USA","status":"current","invested_year":2020,"exit_year":null,"fund_name":"Fund IV","source_url":"https://kpsfund.com/investments/lufkin-industries/","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"C&D Technologies","slug":"c-and-d-technologies","domain":"cdtechno.com","description":"Manufacturer of systems for the conversion and storage of electrical power, including industrial batteries and electronics.","sector":null,"hq":"USA","status":"current","invested_year":2017,"exit_year":null,"fund_name":"Fund IV","source_url":"https://kpsfund.com/investments/cd/","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Life Fitness","slug":"life-fitness","domain":"lifefitness.com","description":"Maker of commercial fitness equipment and game tables.","sector":null,"hq":"USA","status":"current","invested_year":2019,"exit_year":null,"fund_name":"Fund IV","source_url":"https://kpsfund.com/investments/life-fitness/","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null},{"name":"Autokiniton Global Group","slug":"autokiniton-global-group","domain":"agglp.com","description":"Automotive supply platform created by KPS that acquired L&W, a Tier 1 supplier of metal stampings and welded assemblies.","sector":null,"hq":"USA","status":"current","invested_year":2018,"exit_year":null,"fund_name":"Fund IV","source_url":"https://kpsfund.com/investments/autokiniton-global-group-lp/","deal_value":null,"deal_currency":null,"deal_value_basis":null,"stake_pct":null,"co_investors":[],"deal_source_url":null}],"deals":[]}$pf$::jsonb;
  n_companies int;
  n_deals int;
begin
  select id into gp from public.companies
   where category = 'GP' and name = 'KPS Capital Partners'
   order by (source = 'master_directory') desc nulls last, created_at
   limit 1;
  if gp is null then raise exception 'sponsor % is not in the directory', 'KPS Capital Partners'; end if;

  insert into public.portfolio_companies as pc (external_key, gp_company_id, name, domain, description, sector, hq, status, invested_year, exit_year, fund_name,
      source, source_url, deal_value, deal_currency, deal_value_basis, stake_pct, co_investors, deal_source_url, researched_at)
  select gp::text || ':' || (c->>'slug'), gp, c->>'name', c->>'domain', c->>'description', c->>'sector', c->>'hq', c->>'status',
         (c->>'invested_year')::int, (c->>'exit_year')::int, c->>'fund_name', 'web_research', c->>'source_url',
         (c->>'deal_value')::numeric, c->>'deal_currency', c->>'deal_value_basis', (c->>'stake_pct')::numeric,
         coalesce(array(select jsonb_array_elements_text(c->'co_investors')), '{}'), c->>'deal_source_url', now()
    from jsonb_array_elements(doc->'companies') c
  on conflict (external_key) do update set
    name = case when pc.source = 'manual' then pc.name else excluded.name end,
    domain = coalesce(pc.domain, excluded.domain),
    description = case when pc.source = 'manual' then coalesce(pc.description, excluded.description) else coalesce(excluded.description, pc.description) end,
    sector = case when pc.source = 'manual' then coalesce(pc.sector, excluded.sector) else coalesce(excluded.sector, pc.sector) end,
    hq = case when pc.source = 'manual' then coalesce(pc.hq, excluded.hq) else coalesce(excluded.hq, pc.hq) end,
    status = coalesce(excluded.status, pc.status),
    invested_year = coalesce(excluded.invested_year, pc.invested_year),
    exit_year = coalesce(excluded.exit_year, pc.exit_year),
    fund_name = coalesce(excluded.fund_name, pc.fund_name),
    source_url = case when pc.source = 'manual' then coalesce(pc.source_url, excluded.source_url) else excluded.source_url end,
    deal_value = coalesce(excluded.deal_value, pc.deal_value),
    deal_currency = case when excluded.deal_value is not null then excluded.deal_currency else pc.deal_currency end,
    deal_value_basis = case when excluded.deal_value is not null then excluded.deal_value_basis else pc.deal_value_basis end,
    stake_pct = coalesce(excluded.stake_pct, pc.stake_pct),
    co_investors = case when cardinality(excluded.co_investors) > 0 then excluded.co_investors else pc.co_investors end,
    deal_source_url = coalesce(excluded.deal_source_url, pc.deal_source_url),
    researched_at = now();
  get diagnostics n_companies = row_count;

  insert into public.deals as d (external_key, date, date_text, kind, asset_class, target, target_kind, target_key, target_website, investor, investor_company_id,
      co_investors, seller, round, stake_pct, amount, currency, amount_basis, valuation, valuation_currency, headline, summary, source_name, source_url,
      evidence, verified, source)
  select x->>'key', (x->>'date')::date, x->>'date_text', x->>'kind', x->>'asset_class', x->>'target', 'company',
         public.borrower_key(coalesce(x->>'portco_name', x->>'target')), x->>'target_website', x->>'investor',
         case when (x->>'sponsor_is_investor')::boolean then gp else (select m.company_id from ingest.match_firm(x->>'investor', array['GP']) m) end,
         coalesce(array(select jsonb_array_elements_text(x->'co_investors')), '{}'), x->>'seller', x->>'round', (x->>'stake_pct')::numeric,
         (x->>'amount')::numeric, x->>'currency', x->>'amount_basis', (x->>'valuation')::numeric, x->>'valuation_currency',
         x->>'headline', x->>'summary', x->>'source_name', x->>'source_url', x->>'evidence', (x->>'verified')::boolean, 'web_research'
    from jsonb_array_elements(doc->'deals') x
  on conflict (external_key) do update set
    date = excluded.date, date_text = excluded.date_text, kind = excluded.kind, target = excluded.target, target_key = excluded.target_key,
    target_website = coalesce(excluded.target_website, d.target_website), investor = excluded.investor,
    investor_company_id = coalesce(excluded.investor_company_id, d.investor_company_id),
    co_investors = (select coalesce(array_agg(distinct v), '{}') from unnest(d.co_investors || excluded.co_investors) v),
    seller = coalesce(excluded.seller, d.seller), round = coalesce(excluded.round, d.round), stake_pct = coalesce(excluded.stake_pct, d.stake_pct),
    amount = excluded.amount, currency = excluded.currency, amount_basis = excluded.amount_basis,
    valuation = excluded.valuation, valuation_currency = excluded.valuation_currency, headline = excluded.headline,
    summary = coalesce(excluded.summary, d.summary), source_name = excluded.source_name, source_url = excluded.source_url,
    evidence = excluded.evidence, verified = coalesce(excluded.verified, d.verified);
  get diagnostics n_deals = row_count;

  update public.companies set portfolio_note = 'kpsfund.com WordPress REST endpoint /wp-json/wp/v2/investments?parent=0&per_page=100 (60 top-level investments) plus each /investments/<slug>/ page for fund, location, status, website and description; /investments/?status=Active|Inactive and ?fund= filters cross-checked; years from KPS''s own dated acquisition/sale press releases (/wp-json/wp/v2/news, 376 items)', portfolio_researched_at = now() where id = gp;
  insert into ingest.log (what, detail) values ('load_portfolio', jsonb_build_object('sponsor', 'KPS Capital Partners', 'companies', n_companies, 'deals', n_deals));
end $pfdo$;
